app.get('/api/routing/savings', rateLimit('read'), (req, res) => {
  const runs = loadAgentRuns();
  const routing = loadModelRouting();

  let allOpusCost = 0, routedCost = 0;
  for (const run of runs) {
    const tokens = run.estimatedTokens || 0;
    const inputTokens = Math.ceil(tokens * 0.7); // ~70% input
    const outputTokens = tokens - inputTokens;

    // Cost if everything ran on Opus
    allOpusCost += (inputTokens * 15 + outputTokens * 75) / 1_000_000;

    // Cost with routing
    let model = 'sonnet'; // default
    for (const rule of routing.rules) {
      if (rule.agents && rule.agents.includes(run.agentName)) { model = rule.model; break; }
    }
    const costs = routing.costs[model] || routing.costs.sonnet;
    routedCost += (inputTokens * costs.input + outputTokens * costs.output) / 1_000_000;
  }

  res.json({
    totalRuns: runs.length,
    allOpusCost: Math.round(allOpusCost * 10000) / 10000,
    routedCost: Math.round(routedCost * 10000) / 10000,
    savings: Math.round((1 - routedCost / (allOpusCost || 1)) * 100),
    message: `Estimated ${Math.round((1 - routedCost / (allOpusCost || 1)) * 100)}% savings with model routing`,
  });
});

// ── Global error handler ──────────────────────────────────────────────────────
app.use((err, req, res, _next) => {
  console.error(`[ERROR] ${req.method} ${req.url}:`, err.message);
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' ? 'Internal server error' : err.message,
  });
});

// ── Uncaught error safety net ─────────────────────────────────────────────────

export const deleteAgentGoal = (id: string) =>
  request(`/goals/agent/${id}`, { method: 'DELETE' })

// ── Agent Run Analytics ──────────────────────────────────────────────────────
export interface AgentRunEntry {
  id: string
  agentName: string
  prompt: string
  source: 'playground' | 'orchestration' | 'schedule' | 'webhook' | 'sdk' | 'ai-chat'
  timestamp: string
  duration: number
  status: 'success' | 'error'
  promptChars: number
  outputChars: number
  estimatedTokens: number
  estimatedCost: number
  error: string | null
  metadata: Record<string, unknown>
}

export interface AgentAnalyticsSummary {
  [agentName: string]: {
    runCount: number
    avgDuration: number
    successRate: number
    totalEstimatedCost: number
    totalTokens: number
  }
}

export const getAnalyticsRuns = (params?: {
  agent?: string; status?: string; source?: string; from?: string; to?: string; limit?: number; offset?: number
}) => {
  const qs = new URLSearchParams()
  if (params?.agent) qs.set('agent', params.agent)
  if (params?.status) qs.set('status', params.status)
  if (params?.source) qs.set('source', params.source)
  if (params?.from) qs.set('from', params.from)
  if (params?.to) qs.set('to', params.to)
  if (params?.limit) qs.set('limit', String(params.limit))
  if (params?.offset) qs.set('offset', String(params.offset))
  return request<{ total: number; runs: AgentRunEntry[] }>(`/analytics/runs?${qs.toString()}`)
}

export const getAnalyticsSummary = () => request<AgentAnalyticsSummary>('/analytics/summary')

// ── Schedules ────────────────────────────────────────────────────────────────
export interface Schedule {
  id: string
  name: string
  agentName: string
  prompt: string
  cron: string
  enabled: boolean
  createdAt: string
  updatedAt: string
  lastRunAt: string | null
  lastRunStatus: string | null
}

export const getSchedules = () => request<Schedule[]>('/schedules')
export const createSchedule = (data: { name: string; agentName: string; prompt: string; cronExpr: string; enabled?: boolean }) =>
  request<Schedule>('/schedules', { method: 'POST', body: JSON.stringify(data) })
export const updateSchedule = (id: string, data: Partial<{ name: string; agentName: string; prompt: string; cronExpr: string; enabled: boolean }>) =>
  request<Schedule>(`/schedules/${id}`, { method: 'PUT', body: JSON.stringify(data) })
export const deleteSchedule = (id: string) =>
  request(`/schedules/${id}`, { method: 'DELETE' })

// ── Webhooks ─────────────────────────────────────────────────────────────────
export interface Webhook {
  id: string
  name: string
  agentName: string | null
  orchestrationId: string | null
  secret: string
  createdAt: string
  lastTriggeredAt: string | null
  triggerCount: number
}

