import { NavLink, useLocation, useNavigate } from 'react-router-dom'
import { useState, useEffect, useCallback, useRef } from 'react'
import {
  LayoutDashboard,
  FileText,
  Bot,
  FolderOpen,
  Settings,
  ChevronRight,
  ChevronDown,
  Zap,
  Terminal,
  ShieldCheck,
  Sparkles,
  FlaskConical,
  Wrench,
  BookOpen,
  Network,
  Sun,
  Moon,
  Brain,
  CloudUpload,
  Maximize,
  Minimize,
  LayoutTemplate,
  BarChart3,
  Activity,
  Clock,
  Globe,
  Users,
  UserCog,
  Target,
  Search,
  Check,
} from 'lucide-react'
import type { Project } from '../types'
import { useTheme } from '../contexts/ThemeContext'

interface SidebarProps {
  projects: Project[]
}

const navLinkClass = ({ isActive }: { isActive: boolean }) =>
  `flex items-center gap-3 px-4 py-1.5 text-[13px] rounded-lg mx-2 transition-all ${
    isActive
      ? 'bg-accent-muted text-accent-hover font-medium'
      : 'text-text-secondary hover:text-text hover:bg-surface-2'
  }`

function CollapsibleSection({ title, children, defaultOpen = true, count }: {
  title: string
  children: React.ReactNode
  defaultOpen?: boolean
  count?: number
}) {
  const [open, setOpen] = useState(defaultOpen)
  return (
    <div>
      <button
        onClick={() => setOpen(!open)}
        className="w-full flex items-center justify-between px-5 mb-1 group cursor-pointer"
      >
        <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted group-hover:text-text-secondary transition-colors">
          {title}
        </p>
        <div className="flex items-center gap-1.5">
          {count !== undefined && (
            <span className="text-[9px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded-full">{count}</span>
          )}
          {open
            ? <ChevronDown className="w-3 h-3 text-text-muted" />
            : <ChevronRight className="w-3 h-3 text-text-muted" />
          }
        </div>
      </button>
      {open && children}
    </div>
  )
}

function ProjectSelector({ projects }: { projects: Project[] }) {
  const [open, setOpen] = useState(false)
  const location = useLocation()
  const navigate = useNavigate()
  const ref = useRef<HTMLDivElement>(null)

  // Find active project
  const activeProject = projects.find(p => location.pathname.includes(`/projects/${p.id}`))

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false)
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [])

  if (projects.length === 0) return null

  return (
    <div ref={ref} className="relative">
      <button
        onClick={() => setOpen(!open)}
        className={`w-full flex items-center gap-2.5 px-3 py-2 text-[13px] rounded-xl border transition-all ${
          activeProject
            ? 'bg-accent/8 border-accent/20 text-accent-hover'
            : 'bg-surface-2/50 border-border text-text-secondary hover:bg-surface-2 hover:text-text'
        }`}
      >
        <FolderOpen className="w-4 h-4 shrink-0" />
        <span className="flex-1 text-left truncate font-medium">
          {activeProject ? activeProject.name : 'Select project...'}
        </span>
        <div className="flex items-center gap-1 shrink-0">
          <span className="text-[9px] bg-surface-2 text-text-muted px-1.5 py-0.5 rounded-full">{projects.length}</span>
          <ChevronDown className={`w-3.5 h-3.5 text-text-muted transition-transform ${open ? 'rotate-180' : ''}`} />
        </div>
      </button>

      {/* Dropdown */}
      {open && (
        <div className="absolute left-0 right-0 bottom-full mb-1 bg-surface border border-border rounded-xl shadow-xl z-50 overflow-hidden">
          <div className="py-1 max-h-[280px] overflow-y-auto">
            {projects.map((p) => {
              const isActive = activeProject?.id === p.id
              return (
                <button
                  key={p.id}
                  onClick={() => { navigate(`/projects/${p.id}`); setOpen(false) }}
                  className={`w-full flex items-center gap-3 px-3 py-2 text-[13px] transition-colors ${
                    isActive
                      ? 'bg-accent/10 text-accent-hover'
                      : 'text-text-secondary hover:bg-surface-2 hover:text-text'
                  }`}
                >
                  <FolderOpen className="w-3.5 h-3.5 shrink-0" />
                  <span className="flex-1 text-left truncate">{p.name}</span>
                  <div className="flex items-center gap-2 shrink-0">
                    {p.agentCount > 0 && (
                      <span className="text-[9px] text-text-muted bg-surface-2 px-1.5 py-0.5 rounded-full">
                        {p.agentCount} agents
                      </span>
                    )}
                    {isActive && <Check className="w-3.5 h-3.5 text-accent" />}
                  </div>
                </button>
              )
            })}
          </div>
        </div>
      )}
    </div>
  )
}

export default function Sidebar({ projects }: SidebarProps) {
  const location = useLocation()
  const { theme, toggle } = useTheme()
  const [isFullscreen, setIsFullscreen] = useState(false)

  useEffect(() => {
    const handler = () => setIsFullscreen(!!document.fullscreenElement)
    document.addEventListener('fullscreenchange', handler)
    return () => document.removeEventListener('fullscreenchange', handler)
  }, [])

  const toggleFullscreen = useCallback(() => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen()
    } else {
      document.exitFullscreen()
    }
  }, [])

  const isInAutomation = ['/analytics', '/runs', '/schedules', '/webhooks'].some(p => location.pathname.startsWith(p))
  const isInConfig = ['/global', '/memory', '/backup', '/how-it-works', '/setup', '/docs', '/settings'].some(p => location.pathname.startsWith(p))

  return (
    <aside className="w-[240px] min-w-[240px] h-screen sticky top-0 bg-surface border-r border-border flex flex-col">
      {/* Logo */}
      <div className="px-4 py-3 border-b border-border">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-7 h-7 rounded-lg bg-accent flex items-center justify-center shrink-0">
              <Zap className="w-3.5 h-3.5 text-white" />
            </div>
            <h1 className="text-[14px] font-semibold tracking-tight">Polyglot</h1>
          </div>
          <div className="flex items-center gap-0.5 shrink-0">
            <button
              onClick={toggleFullscreen}
              title={isFullscreen ? 'Exit fullscreen' : 'Fullscreen'}
              className="p-1 rounded-md text-text-muted hover:text-text hover:bg-surface-2 transition-all"
            >
              {isFullscreen ? <Minimize className="w-3.5 h-3.5" /> : <Maximize className="w-3.5 h-3.5" />}
            </button>
            <button
              onClick={toggle}
              title={theme === 'light' ? 'Dark mode' : 'Light mode'}
              className="p-1 rounded-md text-text-muted hover:text-text hover:bg-surface-2 transition-all"
            >
              {theme === 'light' ? <Moon className="w-3.5 h-3.5" /> : <Sun className="w-3.5 h-3.5" />}
            </button>
          </div>
        </div>
      </div>

      {/* Search */}
      <button
        onClick={() => window.dispatchEvent(new KeyboardEvent('keydown', { key: 'k', metaKey: true }))}
        className="mx-3 mt-3 mb-2 flex items-center gap-2 px-3 py-1.5 text-xs text-text-muted bg-surface-2/50 border border-border rounded-lg hover:bg-surface-2 hover:text-text transition-colors"
      >
        <Search className="w-3.5 h-3.5" />
        <span className="flex-1 text-left">Search...</span>
        <kbd className="text-[9px] bg-surface border border-border px-1 py-0.5 rounded font-mono">⌘K</kbd>
      </button>

      {/* Navigation */}
      <nav className="flex-1 overflow-y-auto py-2 space-y-3">

        {/* Core */}
        <div>
          <NavLink to="/" className={navLinkClass} end>
            <LayoutDashboard className="w-4 h-4" />
            Dashboard
          </NavLink>
          <NavLink to="/agents" className={navLinkClass}>
            <Bot className="w-4 h-4" />
            Agents
          </NavLink>
          <NavLink to="/orchestration" className={navLinkClass}>
            <Sparkles className="w-4 h-4" />
            Orchestration
          </NavLink>
          <NavLink to="/playground" className={navLinkClass}>
            <FlaskConical className="w-4 h-4" />
            Playground
          </NavLink>
        </div>

        {/* Strategy */}
        <CollapsibleSection title="Strategy">
          <NavLink to="/org-chart" className={navLinkClass}>
            <Users className="w-4 h-4" />
            Org Chart
          </NavLink>
          <NavLink to="/hr" className={navLinkClass}>
            <UserCog className="w-4 h-4" />
            HR
          </NavLink>
          <NavLink to="/goals" className={navLinkClass}>
            <Target className="w-4 h-4" />
            Goals
          </NavLink>
          <NavLink to="/analytics" className={navLinkClass}>
            <BarChart3 className="w-4 h-4" />
            Analytics
          </NavLink>
        </CollapsibleSection>

        {/* Automation */}
        <CollapsibleSection title="Automation" defaultOpen={isInAutomation}>
          <NavLink to="/schedules" className={navLinkClass}>
            <Clock className="w-4 h-4" />
            Schedules
          </NavLink>
          <NavLink to="/webhooks" className={navLinkClass}>
            <Globe className="w-4 h-4" />
            Webhooks
          </NavLink>
          <NavLink to="/runs" className={navLinkClass}>
            <Activity className="w-4 h-4" />
            Run History
          </NavLink>
        </CollapsibleSection>

        {/* Config */}
        <CollapsibleSection title="Config" defaultOpen={isInConfig}>
          <NavLink to="/global/claude-md" className={navLinkClass}>
            <FileText className="w-4 h-4" />
            CLAUDE.md
          </NavLink>
          <NavLink to="/commands" className={navLinkClass}>
            <Terminal className="w-4 h-4" />
            Commands
          </NavLink>
          <NavLink to="/rules" className={navLinkClass}>
            <ShieldCheck className="w-4 h-4" />
            Rules
          </NavLink>
          <NavLink to="/templates" className={navLinkClass}>
            <LayoutTemplate className="w-4 h-4" />
            Templates
          </NavLink>
          <NavLink to="/memory" className={({ isActive }) =>
            `flex items-center gap-3 px-4 py-1.5 text-[13px] rounded-lg mx-2 transition-all ${
              isActive || location.pathname.startsWith('/memory')
                ? 'bg-accent-muted text-accent-hover font-medium'
                : 'text-text-secondary hover:text-text hover:bg-surface-2'
            }`
          }>
            <Brain className="w-4 h-4" />
            Memory
          </NavLink>
          <NavLink to="/backup" className={navLinkClass}>
            <CloudUpload className="w-4 h-4" />
            Backup
          </NavLink>
          <NavLink to="/settings" className={navLinkClass}>
            <Settings className="w-4 h-4" />
            Settings
          </NavLink>
        </CollapsibleSection>

        {/* Help */}
        <CollapsibleSection title="Help" defaultOpen={false}>
          <NavLink to="/how-it-works" className={navLinkClass}>
            <Network className="w-4 h-4" />
            How It Works
          </NavLink>
          <NavLink to="/setup" className={navLinkClass}>
            <Wrench className="w-4 h-4" />
            Setup
          </NavLink>
          <NavLink to="/docs" className={({ isActive }) =>
            `flex items-center gap-3 px-4 py-1.5 text-[13px] rounded-lg mx-2 transition-all ${
              isActive || location.pathname.startsWith('/docs')
                ? 'bg-accent-muted text-accent-hover font-medium'
                : 'text-text-secondary hover:text-text hover:bg-surface-2'
            }`
          }>
            <BookOpen className="w-4 h-4" />
            Docs
          </NavLink>
        </CollapsibleSection>
      </nav>

      {/* Projects — sticky footer */}
      <div className="border-t border-border p-2">
        <ProjectSelector projects={projects} />
      </div>
    </aside>
  )
}

