function logWitnessEvent({ agent, runId, classification, meta = {} }) {
  const entry = {
    t: new Date().toISOString(),
    agent,
    runId: runId || null,
    class: classification,
    ...meta,
  };
  appendJsonl(WITNESS_LOG, entry);
  return entry;
}

function getWitnessLog({ agent, days = 30, limit = 500 } = {}) {
  const all = readJsonl(WITNESS_LOG);
  const cutoff = Date.now() - days * 24 * 60 * 60 * 1000;
  let filtered = all.filter((e) => new Date(e.t).getTime() >= cutoff);
  if (agent) filtered = filtered.filter((e) => e.agent === agent);
  return filtered.slice(-limit);
}

